-- =====================================================================
-- EXPERIMENT 04: Query Execution Plan Analysis (EXPLAIN)
-- Author: Ashmit Tiwari
-- Database: MySQL 8.0+
-- Description: Analyzes query execution plans generated by the MySQL
--              optimizer to evaluate join strategies, table access types,
--              key utilization, and estimated row lookups.
-- =====================================================================

-- 1. Execution Plan: INNER JOIN (Employee & Department)
-- Analyzes index lookup on Department primary key vs full/index scan on Employee.
EXPLAIN
SELECT E.emp_name, D.dept_name
FROM Employee E
INNER JOIN Department D
    ON E.dept_id = D.dept_id;

-- 2. Execution Plan: LEFT JOIN (Department & Employee)
-- Evaluates outer join preservation and join buffer usage.
EXPLAIN
SELECT D.dept_name, E.emp_name
FROM Department D
LEFT JOIN Employee E
    ON D.dept_id = E.dept_id;

-- 3. Execution Plan: Correlated Subquery
-- Evaluates dependency tracking (DEPENDENT SUBQUERY) and repeated scans per outer row.
EXPLAIN
SELECT E.emp_name, E.salary
FROM Employee E
WHERE E.salary > (
    SELECT AVG(E2.salary)
    FROM Employee E2
    WHERE E2.dept_id = E.dept_id
);

-- 4. Execution Plan: EXISTS Semi-Join / Subquery
-- Evaluates semi-join transformation and early-exit index lookups in Project.
EXPLAIN
SELECT E.emp_name
FROM Employee E
WHERE EXISTS (
    SELECT 1
    FROM Project P
    WHERE P.dept_id = E.dept_id
);

